SELECT (select count(*) from visit_history where cstmr_id = C.cstmr_id)visitCnt ,C.cstmr_name ,C.cstmr_id ,C.cstmr_cd FROM cstmr C WHERE
cstmr_name = #{cstmrName}
AND (right(cellphone,4) = #{digit4} OR right(telephone,4) = #{digit4})

        select
				left(datetime,7) monthly
				,count(*) as visitCnt
			from
				sale_off
			where
				shop_id = #{shopId}
			or
			 	shop_id=#{shopNum}
			group by monthly
			having  monthly  >=  #{sdate}
			and
				monthly  <=  #{edate}
